  FOR DELETE
  TO PUBLIC
  USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert own favorite teams" ON "public"."favorite_teams"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((auth.uid() = user_id));

