  TO PUBLIC
  USING ((auth.uid() = user_id));

CREATE POLICY "Authenticated users can read team memberships" ON "public"."league_teams"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."leagues"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Users can delete own subscribed leagues" ON "public"."subscribed_leagues"
  FOR DELETE
  TO PUBLIC
  USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert own subscribed leagues" ON "public"."subscribed_leagues"
