CREATE POLICY "Authenticated users can read visible teams" ON "public"."teams"
  FOR SELECT
  TO "authenticated"
  USING ((is_visible = true));

CREATE POLICY "Enable read access for all authenticated users" ON "public"."teams"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Prevent delete" ON "public"."user_preferences"
  FOR DELETE
  TO PUBLIC
  USING (false);

COMMENT ON EXTENSION "pg_cron" IS 'Job scheduler for PostgreSQL';

COMMENT ON EXTENSION "pg_net" IS 'Async HTTP';

REVOKE ALL ON FUNCTION "public"."apply_league_team_sync"(bigint, bigint, date, date, jsonb) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."apply_league_team_sync"(bigint, bigint, date, date, jsonb) TO "postgres", "service_role";

GRANT EXECUTE ON FUNCTION "public"."auto_set_user_id"() TO PUBLIC, "anon", "authenticated", "postgres", "service_role";

REVOKE ALL ON FUNCTION "public"."claim_due_match_alerts"(integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."claim_due_match_alerts"(integer) TO "postgres", "service_role";

REVOKE ALL ON FUNCTION "public"."get_current_teams_for_leagues"(text[]) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_current_teams_for_leagues"(text[]) TO "authenticated", "postgres", "service_role";

GRANT EXECUTE ON FUNCTION "public"."prepare_match_alert"() TO PUBLIC, "anon", "authenticated", "postgres", "service_role";

GRANT EXECUTE ON FUNCTION "public"."update_timestamp"() TO PUBLIC, "anon", "authenticated", "postgres", "service_role";

GRANT EXECUTE ON FUNCTION "public"."update_updated_at_column"() TO PUBLIC, "anon", "authenticated", "postgres", "service_role";

